import { useParams } from 'react-router-dom'

import './UserPage.css'
import axios from 'axios'
import { useEffect, useState } from 'react'

const UserPage = ()=>{
    const {id} = useParams()
    const [data,setData] = useState([])
    // const [user, setUser] = useState([])
    useEffect(()=>{axios('http://localhost:3001/users').then((res)=>setData(res.data))},[])

const user = data.find((item)=> item.id === id)



// setUser(data.find((item)=> item.id === id))
    // console.log(data.find((item)=> item.id === id));
    // user = data.find((item)=> item.id === id)
    console.log(user);

    return(
        <div>
            <img src={user.image} alt="" />
            <div className='firstData'>
                <p>{user.firstName} {user.lastName} {user.maidenname}</p>
                <p>Age: {user.age}</p>
                <p>Gender: {user.gender}</p>
                <p>{user.email}</p>
                <p>{user.phone}</p>
                <p>{user.birthDate}</p>
            </div>
        </div>
    )
}

export default UserPage
